/** Top-level keys we allow in a Spectral ruleset. Notably excludes `functions`,
 *  which would allow arbitrary custom function code to be loaded. */
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'formats',
  'aliases',
  'overrides',
  'parserOptions',
]);

/** Valid Spectral severity strings usable as a rule shorthand. */
const SEVERITY_STRINGS = new Set(['error', 'warn', 'info', 'hint', 'off']);

/** Spectral's built-in functions. Custom functions are not permitted. */
const BUILTIN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

/** Tokens that could be used for prototype pollution. */
const PROTOTYPE_POLLUTING_TOKENS = ['__proto__', 'prototype', 'constructor'];

type ValidationResult = { isValid: true } | { isValid: false; error: string };

/**
 * Normalizes a value to an array: `undefined` becomes `[]`, an array is
 * returned unchanged, and any other value is wrapped in a single-element array.
 */
export function toArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) {
    return [];
  }

  return Array.isArray(value) ? value : [value];
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** Validates a `documentationUrl` value. Non-string values are ignored. */
function validateDocumentationUrl(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return 'A "documentationUrl" must be a valid https URL.';
  }

  if (url.protocol !== 'https:') {
    return 'A "documentationUrl" must use the https scheme.';
  }

  return null;
}

