 * rulesets and constructs that could be used maliciously (custom functions,
 * prototype pollution, non-https documentation links, etc.).
 */
export function validateSpectralRuleset(content: string): ValidationResult {
  if (!content || content.trim() === '') {
    return { isValid: false, error: 'The ruleset is empty.' };
  }

  let parsed: unknown;
  try {
    parsed = YAML.parse(content);
  } catch {
    return { isValid: false, error: 'The ruleset could not be parsed as YAML or JSON.' };
  }

