    return { isValid: false, error: 'The ruleset must be an object.' };
  }

  const ruleset = parsed;
  const keys = Object.keys(ruleset);

  if (keys.length === 0) {
    return { isValid: false, error: 'The ruleset must declare at least one of "extends" or "rules".' };
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return { isValid: false, error: `Unsupported top-level key "${key}" in ruleset.` };
